def restore(url,digest,size,prefix,dest):
    packed=OUT/'restore.tar.gz';fetch(BASE+url,digest,packed);assert packed.stat().st_size==size
    dest.mkdir(parents=True,exist_ok=False)
    with tarfile.open(packed) as tar:
        members=tar.getmembers();assert len(members)==len({m.name for m in members})
        for m in members:
            path=Path(m.name);assert not path.is_absolute() and '..' not in path.parts and (m.isdir()or m.isfile())
            assert m.name==prefix.rstrip('/') or m.name.startswith(prefix)
            if not m.isfile():continue
            rel=m.name[len(prefix):];assert rel and '..'not in Path(rel).parts and not Path(rel).is_absolute()
            target=dest/rel;target.parent.mkdir(parents=True,exist_ok=True);target.write_bytes(tar.extractfile(m).read())
    packed.unlink()
